mapper.select:
select *
from ${dynamicTableNameProxy.collaborateProduceProcessReport} a

where enterprise_code=${dynamicTableNameProxy.enterpriseCode}
and delete_flag=false

and ${dynamicTableNameProxy.getProductPartSearchObj("a.product_code",data.keyWord)}



    and exists (
    select 1 from ${dynamicTableNameProxy.productPartProcedure} b where a.procedure_code=b.primary_key

    and b.enterprise_code=${dynamicTableNameProxy.enterpriseCode}
    and b.delete_flag=false

    and b.product_part_procedure_sign like '%'||#{data.procedureName}||'%'
    )




    and exists (
    select 1 from ${dynamicTableNameProxy.productPartProcedure} b where a.procedure_code=b.primary_key
    and b."number" like '%'||#{data.procedureNo}||'%'
    and b.enterprise_code=${dynamicTableNameProxy.enterpriseCode}
    and b.delete_flag=false
    )



    and report_user_code in

        #{id}





    and operation_user_code in

        #{id}





    and create_time >= #{ data.startTime}




    and create_time <= #{ data.endTime}



order by create_time desc ,id desc

select COALESCE(sum(work_num) ,0 ) work_num , COALESCE( sum(total_Work_Time)/60,0 ) total_Work_Time
from ${dynamicTableNameProxy.collaborateProduceProcessReport} a

where enterprise_code=${dynamicTableNameProxy.enterpriseCode}
and delete_flag=false



    and exists (
    select 1 from ${dynamicTableNameProxy.productPartProcedure} b where a.procedure_code=b.primary_key
    and b.product_part_procedure_sign like '%'||#{data.procedureName}||'%'
    and b.enterprise_code=${dynamicTableNameProxy.enterpriseCode}
    and b.delete_flag=false
    )




    and exists (
    select 1 from ${dynamicTableNameProxy.productPartProcedure} b where a.procedure_code=b.primary_key
    and b."number" like '%'||#{data.procedureNo}||'%'
    and b.enterprise_code=${dynamicTableNameProxy.enterpriseCode}
    and b.delete_flag=false
    )



    and report_user_code in

        #{id}





    and operation_user_code in

        #{id}





    and create_time >= #{ data.startTime}




    and create_time <= #{ data.endTime}
